            "text": "ثُمَّ بَدَأَتْ تَسْتَعِدُّ لِلذهابِ إِلَى المَدْرَسَةِ، وَفَجْأَةً تَذَكَّرَتْ وَاجِبًا لَمْ تُكْمِلْهْ. خَطَرَتْ لَهَا فِكْرَةٌ نَقْل الإجابات مِنْ إِحْدَى صَدِيقَاتِهَا، لٰكِنَّهَا وَقَفَتْ لَحْظَة وَقَالَتْ فِي نَفْسِهَا: «لَنْ أَفْعَلَ ذٰلِكَ، فَأَنَا أَتَعَلَّم لِأَفْهَمُ، وَلَنْ أَصْل إِلَى الفَهْمِ بِالغِشِّ. اللهُ يَرَانِي، وَلَنْ أَخْذَلَ نَفْسِي بِهٰذِهِ الطَّرِيقَة.» أَسْرَعَتْ إِلَى أُمِّهَا، وَطَلَبَتْ مُسَاعَدَتُهَا. فَلَمْ تَتَرَدَّدْ الأُمُّ فِي دَعَمهَا، وساعدتها فِي إِنْجَاز جُزْء مِنَ الوَاجِبِ. شَعَرَتْ حُورُ بِرَاحَةِ كَبِيرَة، وَكَأَنْ اللهُ قَدْ كَافِأهَا عَلَى إِخْلَاصهَا بِأَنّ مَنْحهَا العَوَن. فِي المَدْرَسَةِ، سَأَلَتْهَا المُعَلِّمَةُ عَنْ الوَاجِبِ النَّاقِصِ. فصدقتها حُورُ وَشَرَحَتْ لَهَا المَوْقِفَ. لَمْ تَعَاقُبهَا المُعَلِّمَةُ، بَلْ مَنَحَتْهَا فُرْصَةً ثَمِينَة لتحسين وَاجِبَهَا. فَرِحَتْ حُورُ فَرَحًا شَدِيدًا لِهٰذِهِ الثِّقَة. وَفِي اليَوْمَ التَّالِي، قَدَّمَتْ وَاجِبَهَا بِشَكْل مُتْقَن، فَكَانَ الأَجْمَلَ بَيْنَ زَمِيلَاتِهَا. أَدْرَكَتْ حُورُ أَنَّ النَّجَاحَ الحَقِيقِيُّ لَا يَحْتَاج إِلَى طُرُق مختصرة، بَلْ إِلَى إِخْلَاص وَنَيَة صَادِقَةٍ، حَتَّى لَوْ وَاجَهَتْ عقبات. وَفِي لَحْظَة مِنَ الصّفاءِ، ابْتَسَمَتْ وَهَمَسَتْ: «عِنْدَمَا أَخْلَصُ لِلهِ، يَكْفِينِي، وَيَمْنَحنِي القُوَّة لِأَنّ أَكُونَ أَفْضَل. اللهُ يَرَى كُلّ شَيْءٍ، وسأجعل كُلّ عَمَلِي خَالِصًا لَهُ وَحْدَهُ.»"
