            "img": "assets/y7/rights/r7.jpg",
            "text": "وَأَمَّا حَقُّ رِجْلَيْكَ فَأَنْ لَا تَمْشِي بهِمَا إِلَى مَا لَا يَحِلُّ لَكَ وَلَا تَجْعَلْهُمَا مَطِيَّتَكَ فِي الطَّرِيقِ الْمُسْتَخِفَّةِ بأَهْلِهَا فِيهَا فَإنَّهَا حَامِلَتُكَ وَسَالِكَةٌ بِكَ مَسْلَكَ الدِّينِ وَالسَّبْقُ لَكَ، وَلَا قُوَّةَ إِلَّا بِاللهِ. مَشَى سُرُورٌ مَعَ أَبِيهِ بِتَوَاضُعٍ وَهُدُوءٍ، وَتَعَلَّمَ أَنَّ حَقَّ الرِّجْلَيْنِ هُوَ السَّعْيُ إِلَى الصَّلَاةِ وَالعِلْمِ وَصِلَةِ الرَّحِمِ، وَعَدَمُ المَشْيِ إِلَى مَكَانٍ فِيهِ أَذًى."
