        "introTitle": "نَبِيُّ اللهِ زَكَرِيَّا عَلَيْهِ السَّلَامُ وَحَرْفُ الكَافِ — الدُّعَاءُ",
        "coverImg": "assets/y4/art/art11.jpg",
