            "text": "وَأَمَّا حَقُّ الصَّدَقَةِ فَأَنْ تَعْلَمَ أنَّها ذُخرُكَ عِنْدَ رَبكَ وَوَديعَتُكَ الَّتِي لَا تَحْتَاجُ إِلَى الإشْهَادِ، فَإِذَا عَلِمْتَ ذَلِك كُنْتَ بِمَا اسْتَودَعْتَهُ سِرًّا أَوْثقَ بِمَا اسْتَوْدَعْتَهُ عَلانِيَةً، وَكُنْتَ جَدِيرًا أَنْ تَكونَ أَسْرَرْتَ إلَيْهِ أَمْرًا أَعْلَنْتَهُ، وَكَانَ الأَمْرُ بَيْنَكَ وبَيْنَهُ فِيهَا سِرًّا عَلَى كُلِّ حَال وَلَمْ تَسْتَظْهِرْ عَلَيْهِ فِيمَا اسْتَوْدَعْتَهُ مِنْهَا بإشْهَادِ الأَسْمَاعِ وَالأَبْصَارِ عَلَيْهِ بِهَا كَأنَّهَا أَوْثقُ فِي نَفْسِكَ لَا كَأنَّكَ لَا تثِقُ بِهِ فِي تَأْديَةِ وَديعَتِكَ إلَيْكَ، ثُمَّ لَمْ تَمْتَنَّ بِهَا عَلَى أَحَد لأَنّهَا لَكَ فَإِذَا امْتَنَنْتَ بِهَا لَمْ تَأْمَنْ أَنْ تَكُونَ بِهَا مِثْلَ تَهْـجِينِ حَالِكَ مِنْهَا إِلَى مَنْ مَنَنْتَ بِهَا عَلَيْهِ لأَنَّ فِي ذلِكَ دَلِيلاً عَلَى أَنّكَ لَمْ تُرِدْ نفْسَكَ بِهَا، وَلَوْ أَرَدْتَ نفْسَكَ بِهَا لَمْ تَمْتَنَّ بِهَا عَلَى أَحَد. وَلَا قُوَّةَ إِلَّا بِاللهِ. وَأمَّا حَقُّ الهَدْيِ فَأَنْ تُخلِصَ بِهَا الإرَادَةَ إِلَى رَبكَ وَالتَّعَرُّضَ لِرَحْمَتِهِ وَقَبُولِهِ وَلَا تُرِيدَ عُيُونَ النَّاظِرِينَ دُونهُ، فـَإذَا كُنْتَ كَذَلِكَ لَمْ تَكُنْ مُتَكَلِّفًا وَلَا مُتَصَنِّعًا وَكُنْتَ إنَّمَا تَقْصِدُ إِلَى اللهِ. وَاعْلَمْ أَنَّ اللهَ يُرَادُ بالْيَسِيرِ وَلَا يُرَادُ بالْعَسِيرِ كَمَا أَرَادَ بخَلْقِهِ التَّيْسِيرَ وَلَمْ يُرِدْ بهِمُ التَّعْسِيرَ، وَكَذَلِكَ التَّذَلُّلَ أَوْلَى بِكَ مِنْ التَّدَهْقُنِ لأَنَّ الْكُلْفَةَ وَالْمَئونَةَ فِي الْمُتَدَهْقِنِينَ. فَأمَّا التَّذَلُّلُ وَالتَّمَسْكُنُ فَلَا كُلْفَةَ فِيهِمَا وَلَا مَئونةَ عَلَيْهِمَا لأَنَّهُمَا الْخِلْقَةَ وهُمَا مَوجُودَانِ فِي الطَّبيعَةِ. وَلَا قُوَّةَ إِلَّا بِاللهِ. شَاهَدَ سُرُورٌ صُورَةَ الكَعْبَةِ المُشَرَّفَةِ وَعَرَفَ أَنَّ الحَجَّ هُوَ وِفَادَةٌ إِلَى بَيْتِ اللهِ الحَرَامِ تَجْمَعُ قُلُوبَ المُؤْمِنِينَ عَلَى التَّوْحِيدِ وَالسَّلَامِ وَالأُخُوَّةْ."
