          {
            "img": "assets/y7/rights/r14.jpg",
            "text": "قَالَ نُورٌ: «أَحْسَنْتِ السُّؤَال، يَا أُخْتِي الصَّغِيرَةُ. الإِخْلَاصِ يَعْنِي أَنْ نَقْصَدَ اللهُ وَحْدَهُ، وَالتَّوْحِيدِ يَعْنِي أَلَا نَعْبُد سَوَاَه. وَسُورَة قُلْ هُوَ اللهُ أَحَد تَجْمَع المعنيين مَعًا.» فَرِحَتْ حُورُ وَقَالَتْ: «فَهِمْتُ الآنَ! وَعِنْدَمَا نُعُود إِلَى البَيْتِ سَأَعْلَم أُخْتِي الصَّغِيرَةُ سُورَة التَّوْحِيدِ، فَهٰذَا واجبي، لِأَنّ المُعَلِّمَ قَالَ: مَنْ تعلَّم عِلْمًا، فَلْيَكُن كَالنَّهْرِ، يَشْرَب وَيَسْقِي غَيْرُهُ.» ابْتَسَمَ نُورٌ وَقَالَ: «أَحْسَنْتِ يَا أُخْتِي، هٰكَذَا يَكُونُ طَالِب العِلْم الصَّادِقِ.» وَفِي المَسَاءِ، جَلَسَتْ حُورُ تَعَلَّمَ أُخْتَهَا الصَّغِيرَةُ السُّورَة. سَأَلَتْهَا أُخْتَهَا: «مَا مَعْنَى الصَّمَد؟» تَرَدَّدَتْ حُورُ، وَلَمْ تَعْرِفْ الجَوَاب، فَاسْتَحَتْ وَقَالَتْ بِتَرَدُّدٍ: «أَظُنُّ أَنَّهُ يَعْنِي الصُّلْب!» سَمِعَتِ الأُمُّ فَقَالَتْ بِرِفْقٍ: «يَا حُورُ، لَا تقولي مَا لَا تَعْرِفِينَ، فَقَوْلِي لَا أَعْلَم أَفْضَل مِنْ قَوْل بِلَا عِلْم، لِأَنّ العِلْمَ أَمَانَة يَا صَغِيرَتِي.» خَفَضَتْ حُورُ رَأْسَهَا بِخَجَلٍ، ثُمَّ قَالَتْ بِهُدُوءٍ: «أَعِدُكِ يَا أُمِّي، أَنْ أَتَعَلَّم أَكْثَر، وَأَحْفَظ الأَمَانَةِ فِي كَلَامِي وَعِلْمِيّ.» ابْتَسَمَتِ الأُمُّ وَقَالَتْ: «هٰكَذَا يَكُونُ الإِخْلَاصِ يَا ابْنَتِي، أَنْ نَطْلَبَ العِلْم لِلهِ، وَنَتَحَدَّث بِمَا نَعْلَمُ، وَنَصَمَتْ عَمَّا لَا نَعْلَمُ.»"
          },
          {
            "img": "assets/y7/rights/r14.jpg",
            "text": "وَنَتَحَلَّى بِآدَابِ الفِطْرَةِ وَالطَّهَارَةِ؛ تَعَلُّمُ خُلُقِ التَّوَاضُعِ وَالتَّبَسُّمِ اللَّطِيفِ مَعَ الضُّعَفَاءِ، وَالنَّزَاهَةِ وَالعِفَّةِ عَنْ قَبُولِ الهَدَايَا الَّتِي يُرَادُ بِهَا التَّنَازُلُ عَنِ الحَقِّ، وَحِفْظِ سَتْرِ الثِّيَابِ وَالأَدَبِ عِنْدَ المَشْيِ، وَالحِرْصِ الشَّدِيدِ عَلَى أَدَاءِ الصَّلَاةِ فِي أَوَّلِ وَقْتِهَا."
          }
