            "text": "نَبِيُّ اللهِ يُوسُفُ عَلَيْهِ السَّلَامُ قُدْوَتُنَا فِي الخَيْرِ؛ حَيْثُ ظَهَرَتْ نَارُ الغَضَبِ وَالحَسَدِ فِي نَارِ الحَسَدِ وَالغَضَبِ فِي قُلُوبِ إِخْوَةِ يُوسُفَ حِينَ أَلْقَوْهُ فِي الجُبِّ، وَنَارُ الهَوَى وَالغَضَبِ الَّتِي أَوْدَعَتْهُ السِّجْنَ ظُلْمًا، وَحَرَارَةُ السِّنِينَ السَّبْعِ العِجَافِ؛ وَفِي مُقَابِلِهَا قُوَّةُ «الدَّفْعِ» النُّورَانِيَّةُ فِي نَفْسِ يُوسُفَ الَّتِي صَرَفَ اللهُ بِهَا عَنْهُ السُّوءَ وَالفَحْشَاءَ، وَكَظْمُهُ الغَيْظَ وَدَفْعُهُ السَّيِّئَةَ بِالحَسَنَةِ عِنْدَ العَفْوِ عَنْ إِخْوَتِهِ، وَنُورُ الشَّمْسِ وَالقَمَرِ وَالكَوَاكِبِ السَّاجِدَةِ. وَهَبَّتْ رِيحُ الوَهْمِ فِي رِيحِ الوَهْمِ وَالكَذِبِ حِينَ جَاءَ إِخْوَتُهُ عَلَى قَمِيصِهِ بِدَمٍ كَذِبٍ وَادَّعَوْا أَنَّ الذِّئْبَ أَكَلَهُ، وَتُهْمَةُ السَّرِقَةِ البَاطِلَةُ؛ وَفِي مُقَابِلِهَا الرِّيحُ الطَّيِّبَةُ الَّتِي حَمَلَتْ عِطْرَ قَمِيصِ يُوسُفَ الجَنِّيِّ مِنْ مِصْرَ إِلَى كَنْعَانَ حَتَّى قَالَ يَعْقُوبُ: ﴿إِنِّي لَأَجِدُ رِيحَ يُوسُفَ﴾. بَيْنَمَا أَشْرَقَ نُورُ العَقْلِ وَالتَّفَكُّرِ فِي صَخْرَةِ قَعْرِ الجُبِّ الَّتِي جَلَسَ عَلَيْهَا يُوسُفُ، وَتَدْبِيرُهُ العَقْلِيُّ العَظِيمُ لِخَزَائِنِ الأَرْضِ وَزِرَاعَةِ التُّرْبَةِ سَبْعَ سِنِينَ دَأَبًا وَحِفْظِ القَمْحِ فِي سُنْبُلِهِ (﴿فَذَرُوهُ فِي سُنبُلِهِ﴾) لِحِمَايَتِهِ مِنَ التَّلَفِ. وَتَجَلَّى صَفَاءُ الطَّاعَةِ وَالتَّوَاضُعِ فِي مَاءِ البِئْرِ الَّذِي أَدْلَى فِيهِ الوَارِدُ دَلْوَهُ، وَمَاءُ النِّيلِ وَالأَمْطَارِ فِي عَامِ الغَوْثِ (﴿فِيهِ يُغَاثُ النَّاسُ وَفِيهِ يَعْصِرُونَ﴾)، وَتَهْذِيبُ يُوسُفَ لِلشَّهْوَةِ بِالعِفَّةِ الكَامِلَةِ وَالزُّهْدِ فِي الطَّعَامِ حَتَّى لَا يَشْبَعَ وَفِي الرَّعِيَّةِ جَائِعٌ."
