            "text": "أَضَافَتْ حُورُ: «وَالعَدْلِ يَعْنِي أَنْ أَرَى أَلْمَكُ حَتَّى لَوْ كُنْتُ أَنَا المتألمة.» اتفقا عَلَى مِيثَاق شَرَف: إِذَا اخْتَلَفَا، سَيَذْكَرَانِ اللهُ أَوَّلًا، ويتنافسان فِي الإِنْصَافِ لَا فِي الانتِصَارِ. وَفِي تِلْكَ اللَّيْلَة، كَتَبْتُ حُورُ فِي مذكرتها: «تَعَلَّمَتْ أَنَّ الحَقَّ لَا ينفصل عَنْ الرَّحْمَةِ، وَأَنْ أَنْصِفْ أَخِي حَتَّى مِنْ نَفْسِي، هِيَ أَعْظَم قُوَّة.» حَقّ الخَصْم الْمُدَّعَى عَلَيْهِ وَأمّا حَقُّ الخَصْمِ الْمُدَّعَى عَلَيهِ فَإنْ كَانَ مَا تدَّعِيهِ حَقًّا أَجْمَلْتَ فِي مُقَاوَلَتِهِ بمَخرَجِ الدَّعْوَى، فَإنّ لِلدَّعْوَى غِلْظَةً فِي سَمْعِ الْمُدَّعَى عَلَيهِ. وَقَصَدْتَ قَصْدَ حُجَّتِكَ بالرِّفْقِ وَأَمْهَلِ الْمُهْلَةِ وَأبْينِ الْبَيَانِ وَألطَفِ اللُّطْفِ ولَمْ تَتشَاغَلْ عَنْ حُجَّتِكَ بمُنازَعَتِهِ بِالقَيَلِ وَالقَالِ فَتَذهَبْ عَنْكَ حُجَّتُكَ وَلَا يَكُونَ لَكَ فِي ذَلِكَ دَرْكٌ. وَلَا قُوَّةَ إِلَّا بِاللهِ. بَعْد أَنْ تُصَالِحَ نُورٌ وَحُورُ حَوْلَ القَلَمِ المَكْسُورِ وَكِتَاب حُورُ المَفْقُودِ، ظَهَرَتْ مُشْكِلَةٌ جَدِيدَة صَغِيرَة: أَثْنَاءَ تَرْتِيب أُحْجِيَةِ الصُّوَرِ، وَجَدْتَ حُورُ أَنْ بَعْض القَطْع مَفْقُودَة أَوْ لَمْ يَضَعهَا نُورٌ فِي مَكَانَهَا الصَّحِيحِ، فَتُهْمتُهُ بِالخَطَأِ أَوْ الإِهْمَال. شَعَرَتْ حُورُ بِالاسْتَيْاَءِ، وَبَدَأَتْ بِالكَلَامِ الحَادّ، لٰكِنْ نُورٌ تَذَكَّرَ حَقّ الخَصْم الْمُدَّعَى عَلَيْهِ: لَمْ يَكُنْ هُوَ سَبَب فِقْدَان القَطْع أَوْ الإِهْمَال عَمْدًا، لِذٰلِكَ تُحْدِث بِهُدُوءٍ وَأَوْضَحُ مَوْقِفَهُ بِاللُّطْفِ. قَالَ نُورٌ: «يَا أُخْتِي، لَمْ أَقْصِدْ خَطَأ فِي تَرْتِيب القَطْع، دعينا نَبْحَثُ مَعًا عَنْ القَطْعِ المَفْقُودَةِ.» أَعْطَى حُورُ فُرْصَةً لِلتَفْهَمُ، وَلَمْ يَغْضَب أَوْ يَرْفَع صَوْتَهُ. لَاحَظَتْ حُورُ هدوءه وأسلوبه اللَّطِيف، وَبَدَأَتْ هِيَ أَيْضًا بِالبَحْثِ بِلَا لَوْم. تَعَلَّمَتْ حُورُ دَرْسًا مَهْمَا: حَتَّى إِذَا شَعَرَتْ بِالخَطَأِ، يَجِبُ الاسْتِمَاع وَالتَّأَكُّد قَبْل إِصْدَار الاتهام. تعمّق شُعُورٌ الأُخُوَّةِ بَيْنَهُمَا، وَأَدْرَكَا أَنَّ الإِنْصَافَ وَالرِّفْق مَعَ الخَصْمِ الْمُدَّعَى عَلَيْهِ يُزِيل الخِلَاف وَيُقَوِّي العلاقة."
