            "text": "وَأمّا حَقُّ مَنْ سَرَّكَ اللهُ بِهِ وَعلَى يَدَيهِ، فَإنْ كَانَ تَعَمَّدَهَا لَكَ حَمِدْتَ اللهَ أَوّلاً ثُمَّ شَكَرْتَهُ عَلَى ذلِكَ بقَدْرِهِ فِي مَوْضِعِ الجَزَاءِ وَكَافَأتَهُ عَلَى فَضْلِ الابْتِدَاءِ وَأَرْصَدْتَ لَهُ الْمُكَافَأَةَ، وَإنْ لَمْ يَكُنْ تَعَمَّدَهَا حَمِدْتَ اللهَ وَشَكَرتَهُ وعَلِمْتَ أنَّهُ مِنْهُ، تَوَحَّدَكَ بِهَا وأَحْبَبتَ هٰذَا إِذْ كَانَ سَبَباً مِنْ أَسْبَاب نِعَمِ اللهُ عَلَيْكَ وَترْجُو لَهُ بَعْدَ ذلِكَ خَيرًا، فإنَّ أَسْبَابَ النِّعَمِ بَرَكَةٌ حَيثُ مَا كَانتْ وَإنْ كَانَ لَمْ يَتَعَمَّدَ. وَلَا قُوَّةَ إِلَّا بِاللهِ. وَأمّا حَقُّ مَنْ سَاءَكَ القَضَاءُ عَلَى يَدَيهِ بقَوْل أَوْ فِعْل فَإنْ كَانَ تَعَمَّدَهَا كَانَ العَفْوُ أَوْلَى بِكَ لِمَا فِيهِ لَهُ مِنْ القَمْعِ وَحُسْنَ الأَدَب مَعَ كَثِيرِ أَمْثالِهِ مِنَ الخَلْقِ، فإنَّ اللهُ يَقُولُ ﴿وَلَمَنِ انتَصَرَ بَعْدَ ظُلْمِهِ فَأُولئِكَ مَا عَلَيْهِمْ مِنْ سَبيلٍ. إنمَّا السَّبِيل عَلَى الَّذين يظْلِمونَ النَّاسَ ويَبغون فِي الأرْضِ بغَيرِ الحَقِّ، أُولئِكَ لَهُمْ عَذابٌ أليِمٌ. وَلمَنْ صَبَرَ وَغَفَرَ إنَّ ذلِكَ لََمِنْ عَزْمِ الأُمُور﴾ وَقَالَ عَزَّ وَجَلَّ ﴿وَإنْ عَاقَبْتُمْ فَعَاقِبُوا بمِثلِ مَا عُوقِبتُمْ بِهِ وَلَئِنْ صَبَرْتُمْ لَهُوَ خَيْرٌ لِلصَّابرِين﴾ هٰذَا فِي الْعَمْدِ فَإنْ لَمْ يَكُنْ عَمْدًا لَمْ تَظْلِمْهُ بتَعَمُّدِ الانتِصَار مِنْهُ فَتَكُونَ قَدْ كَافَأتَهُ فِي تَعَمُّد عَلَى خَطَأ. وَرَفِقْتَ بِهِ وَرَدَدتَهُ بأَلْطَفِ مَا تقْدِرُ عَلَيْهِ. وَلَا قُوَّةَ إِلَّا بِاللهِ. وَأمّا حَقُّ أَهْلِ مِلَّتِكَ عَامَّةً فَإضْمَارُ السَّلامَةِ وَنشْرِ جَنَاحِ الرَّحْمَةِ وَالرِّفْقِ بمُسِيئِهِمْ وَتأَلُّفُهُمْ وَاسْتِصْلاحُهُمْ وَشُكْرُ مُحْسِنِهِمْ إِلَى نفْسِهِ وَإلَيْكَ، فَإنَّ إحْسَانهُ إِلَى نفْسِهِ إحْسَانهُ إلَيكَ إِذَا كَفَّ عَنْكَ أَذاهُ وَكَفَاكَ مَئونتَهُ وَحَبَسَ عَنكَ نفْسَهُ فَعَمِّهِمْ جَمِيعًا بدَعْوَتِكَ وَانصُرْهُمْ جَمِيعـاً بنُصْرَتِكَ وَأَنزَلتَهُمْ جَمِيعاً مِنْكَ مَنَازِلَهُمْ، كَبيرَهُمْ بمَنْزِلَةِ الْوَالِدِ وَصَغِيرَهُمْ بمَنْزِلَةِ الْوَلَدِ وَأَوْسَطَهُمْ بمَنْزِلَةِ الأَخِ. فَمَـنْ أَتاكَ تَعَاهَدْتَه بلُطْف وَرَحْمَة. وَصِلْ أَخَاكَ بِمَا يَجِبُ لِلأَخِ عَلَى أَخِيهِ. وَأمّا حَقُّ أَهْلِ الذِّمَّةِ فَالحُكْمُ فِيهِمْ أَنْ تَقبَلَ مِنْهُمْ مَا قَبِلَ اللهُ، وَتَفِي بِمَا جَعَلَ اللهُ لَهُمْ مِنْ ذِمَّتِهِ وَعَهْدِهِ وَتكِلُهُمْ إلَيهِ فِيمَا طَلبُوا مِنْ أَنْفُسِهِمْ وَأُجْبرُِوا عَلَيْهِ وَتحْكُمَ فِيهِمْ بِمَا حَكَمَ اللهُ بِهِ عَلَى نفْسِكَ فِيمَا جَرَى بَيْنَكَ وَبَيْنَهُمْ مِنْ مُعَامَلَة وَلْيَكُنْ بَينَكَ وَبيْنَ ظُلْمِهِمْ مِنْ رِعَايَةِ ذِمَّةِ اللَّهِ وَالْوَفَاءِ بعَهْدِهِ وَعَهْدِ رَسُولِ اللَّهِ – صَلَّى اللهُ عَلَيْهِ وَآلِهِ – حَائِلٌ فَإنَّهُ بَلَغَنَا أنَّهُ قَالَ “مَنْ ظَلَمَ مُعَاهِدًا كُنْتُ خَصْمَهُ” فَاتَّقِ اللَّهَ. وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللهِ. اخْتَتَمَ سُرُورٌ وَحُورُ كِتَابَ الحُقُوقِ بِالقَاعِدَةِ الذَّهَبِيَّةِ: أَنْ نُحِبَّ لِلنَّاسِ مَا نُحِبُّ لِأَنْفُسِنَا، وَنُعَامِلَ الجَمِيعَ بِالأَمَانَةِ وَالرَّحْمَةِ وَالسَّلَامِ وَالخُلُقِ الحَسَنْ."
