            "img": "assets/y7/rights/r28.jpg",
            "text": "فِي صَبَاحِ يَوْم هَادِئٍ، كَانَتْ حُورُ تَلْعَب مَعَ أُخْتَهَا لِينَا فِي غُرْفَةِ الأَلْعَابِ. فَجْأَةً تَعَالَتِ الأَصْوَاتِ، فَقَدْ ضَرَبَتْ لِينَا أُخْتَهَا حُورُ ظَنًّا مِنْهَا أَنَّهَا أَخَذَتْ لَعِبْتَهَا دُونَ إِذَنْ. دَخَلَ نُورٌ بِسُرْعَةٍ وَحَاوَل تَهَدَّئَتْهُمَا، فَاكْتَشَفَ أَنْ اللُّعْبَةَ لَمْ تَكُنْ أصلًا لِلِينَا، وَأَنَّهَا ظَلَمْتُ أُخْتَهَا دُونَ تأن أَوْ تَأْكَدُ. هدّأ نُورٌ المَوْقِفَ وَقَالَ بِهُدُوءٍ: «لَا يَجُوز أَنْ نَظْلَمَ أَحَدًا أَوْ نَتَهَمَّهُ قَبْل أَنْ نَتَأَكَّدَ مِنَ الحَقِيقَةِ.» تصالحت الأُخْتَانِ وَاعْتَذَرْتُ لِينَا مِنْ حُورِ، ثُمَّ خَرَجُوا جَمِيعًا إِلَى المَدْرَسَةِ. وَفِي الطَّرِيقِ، رَأَى نُورٌ وَحُورُ وَلَدًا يَرْمِي الحِجَارَة نَحْوَ نَافِذَةِ مُنَزَّلْ وَهُوَ يَضْحَكُ دُونَ مُبَالَاَةِ، فَكَاَد أَنْ يَكْسِر الزُّجَاج وَيَتَسَبَّبُ بِالأَذَى. خَرَجَ صَاحِب المَنْزِلِ غَاضِبًا وَطَلَب مِنْ نُورِ وَحُورُ الشَّهَادَة عَلَى مَا رأيا، لٰكِنّهُمَا قَالَا بِأَدَبٍ: «لَقَدْ سَلَمَت النَّافِذَةِ مِنَ الأَذَى وَلِلهِ الحَمْد، لٰكِنْ هٰذَا فِعْل خَاطِئ وَيَجِبُ أَنْ لَا يَتَكَرَّرُ.» اسْتَحْيَا الوَلَد مِنْ كَلَامهُمَا وَابْتَعَدَ. وَبَعْد انْتِهَاء اليَوْمَ الدِّرَاسِيّ وَأَثْنَاءَ عَوْدَتُهُمْ إِلَى البَيْتِ، رَأَوْا الوَلَد نَفْسِهِ يَقُوم بِسَكْبِ الزَّيْتِ عَلَى الطَّرِيقِ حَتَّى يَنْزَلِقُ المَارَّة ويسقطوا! وَقَفَ نُورٌ وَحُورُ بِحَزْمٍ وَنَظَرًا إِلَيْهِ نَظْرَة غَضِبَ وَاسْتِنْكَار، ثُمَّ قررا إخبار وَالِدَتِهِمَا بِمَا فَعَلَهُ. عِنْدَمَا وَصَلَا المَنْزِلِ أخبرا أُمِّهِمَا، فَقَامَتِ الأُمُّ بِالتَّوَاصُلِ مَعَ أَهْل ذٰلِكَ الوَلَد وَأَخْبَرَتْهُمْ بِمَا حَدَث. شَكَر الأَهْل الأُمُّ عَلَى نَصَحهَا، وَاعْتَذَرُوا عَمَّا فَعَلَهُ وُلِدهُمْ، وَقَرَّرُوا معاقبته بِعَدَم السّماح لَهُ بِالخُرُوجِ مِنَ البَيْتِ دُونَ مُرَاقَبَةِ حَتَّى يَتَأَدَّبُ وَيَتَعَلَّم عَدَم إِيذَاء الآخَرِينَ."
